s=s.replace('if(GetFileAttributesW(cancelFile)!=INVALID_FILE_ATTRIBUTES)return 0;', 'if(!recover&&GetFileAttributesW(cancelFile)!=INVALID_FILE_ATTRIBUTES)return 0;')
