s=s.replace('CloseHandle(job);job=NULL;break;', 'CloseHandle(job);job=NULL;if(WaitForSingleObject(child,5000)!=WAIT_OBJECT_0){CloseHandle(child);DestroyWindow(wnd);return 16;}break;')
s=s.replace('if(!hashMatches(path,ACCESS_SHA))return 8;', 'if(!hashMatches(path,ACCESS_SHA))return 8;swprintf(path,32768,L"%ls\\\\Launch-NonUiProcess.ps1",root);if(!hashMatches(path,LAUNCHER_SHA))return 8;swprintf(path,32768,L"%ls\\\\NonUiProcess.cs",root);if(!hashMatches(path,NONUI_SHA))return 8;')
