p=LAB/'Build.py';s=p.read_text().replace("('ACCESS_SHA','Access.cs')", "('ACCESS_SHA','Access.cs'),('LAUNCHER_SHA','Launch-NonUiProcess.ps1'),('NONUI_SHA','NonUiProcess.cs')")
p.write_text(s,encoding='utf-8')
p=LAB/'Controller.ps1';s=p.read_text(encoding='utf-8-sig').replace("if($OwnFixture -ne ($cfg.Scope -eq 'Fixture'))", "if([bool]$OwnFixture -ne ($cfg.Scope -eq 'Fixture'))")
p.write_text(s,encoding='utf-8-sig')
p=LAB/'ElevatedCorners.ps1';s=p.read_text(encoding='utf-8-sig')
s=s.replace("$pointer=Join-Path $data 'current.json';$r=Read-Json $pointer;$hostLease=Exact-Host $r", "$pointer=Join-Path $data 'current.json';$r=Read-Json $pointer;if($r){if($r.Session -notmatch '^[a-f0-9]{32}$' -or $r.Config -ine (Join-Path $data ($r.Session+'.config.json'))){throw 'Invalid current session pointer.'};$validated=Validate-Config $r.Config};$hostLease=Exact-Host $r")
s=s.replace("if($hostLease){if(!$hostLease.Wait(20000)){throw 'Exact high companion did not stop; no foreign/elevated process terminated.'};return}", "if($hostLease){if(!$hostLease.Wait(20000)){throw 'Exact high companion did not stop; no foreign/elevated process terminated.'};$done=Read-Json $c.Status;if(@(Read-Json $c.Journal).Count -or ($done -and $done.Status -notin @('stopped','failed-restored'))){throw 'High restoration remains incomplete; journal retained.'};return}")
s=s.replace("if(!$restore.Wait(25000)){throw 'Elevated recovery still active.'}", "if(!$restore.Wait(25000)){throw 'Elevated recovery still active.'};if(@(Read-Json (Join-Path $data 'high-journal.json')).Count){throw 'Elevated recovery remains incomplete.'}")
s=s.replace("$new=[CornerAccess]::Elevate($record.Path,('--run \"'+$path+'\"'),$PSScriptRoot)", "try{$new=[CornerAccess]::Elevate($record.Path,('--run \"'+$path+'\"'),$PSScriptRoot)}catch{if(!(Test-Path -LiteralPath $cfg.Cancel)){[IO.File]::WriteAllText($cfg.Cancel,'Launch failed/cancelled')};throw}")
